import { useEffect, useState, type CSSProperties } from "react";
import { AlertTriangle, ArrowLeft, ArrowRight, BookOpen, BookOpenCheck, Check, ChevronRight, Clock3, Crown, Flag, Lightbulb, Lock, Map, RotateCcw, ShieldCheck, Sparkles, Target, Trophy, X } from "lucide-react";
import { bossChallenges, quests, type BossChallenge, type Quest, type QuestQuestion } from "@/lib/questionBank";

// Design reminder: brutalist study quest — thick ink borders, paper texture,
// hard offset shadows, loud primary colors, and visible learning recovery.

type RecordValue = { best?: number; last?: number; accuracy: number; attempts: number; hints: number; completed: boolean; bossCleared?: boolean; rewardTitle?: string };
type Records = Record<number, RecordValue>;
type WrongNote = QuestQuestion & { id: string; questId: number; questionIndex: number; selected: string[]; wrongCount: number; lastWrongAt: number };
type Screen = "map" | "brief" | "play" | "boss" | "boss-clear" | "result" | "unlock" | "ending" | "achievements" | "notes" | "note-play" | "mini-review" | "mini-result";
type NoteFilter = number | "all";
type UnlockSequence = { from: number; next: number | null; result: RecordValue };
type MiniReviewItem = QuestQuestion & { questId: number; source: "오답 확인" | "약점 강화" };

type LegacyQuest = Omit<Quest, "questions"> & { questions: Omit<QuestQuestion, "category">[] };
const legacyQuests: LegacyQuest[] = [
  { id: 1, title: "닫힌 문 앞에서", place: "수의 문", concept: "범위가 필요한 상황", summary: "정확한 수, 범위, 어림 중 알맞은 표현을 찾아요.", gate: "범위의 눈", tone: "blue", theory: "수의 범위는 어떤 수가 기준값보다 큰지, 작은지, 또는 기준값을 포함하는지 나타내요.", questions: [{ prompt: "다음 중 ‘수의 범위’로 나타내는 것이 가장 알맞은 상황은 무엇일까요?", options: ["오늘의 정확한 시각", "키가 140cm 이상인 학생", "연필의 정확한 길이", "계산기의 정확한 답"], answers: ["키가 140cm 이상인 학생"], explanation: "‘키가 140cm 이상’처럼 기준에 따라 여러 수를 묶어 나타낼 때 수의 범위를 사용해요.", hint: "기준값을 중심으로 여러 수를 묶는 상황을 찾아보세요." }] },
  { id: 2, title: "채워진 점의 문", place: "이상·이하", concept: "기준값 포함", summary: "이상과 이하에서 기준값도 함께 생각해요.", gate: "채워진 점", tone: "mint", theory: "이상은 기준값과 같거나 큰 수, 이하는 기준값과 같거나 작은 수예요. 기준값을 포함해요.", questions: [{ prompt: "‘120 이상’인 수를 모두 고르세요.", options: ["112", "120", "127", "98"], answers: ["120", "127"], multiple: true, explanation: "이상은 기준값을 포함하고 그보다 큰 수예요. 120과 127이 해당해요.", hint: "‘이상’은 기준값도 포함해요." }] },
  { id: 3, title: "빈 점의 숲", place: "초과·미만", concept: "기준값 제외", summary: "초과와 미만은 기준값을 포함하지 않아요.", gate: "빈 점", tone: "purple", theory: "초과는 기준값보다 큰 수, 미만은 기준값보다 작은 수예요. 기준값은 포함하지 않아요.", questions: [{ prompt: "‘85 미만’인 수를 고르세요.", options: ["85", "84", "90", "76"], answers: ["84", "76"], multiple: true, explanation: "미만은 기준값을 포함하지 않고 그보다 작은 수예요. 84와 76이 해당해요.", hint: "85와 같은 수는 미만에 들어갈 수 없어요." }] },
  { id: 4, title: "경계의 다리", place: "수직선", concept: "범위 나타내기", summary: "채워진 점·빈 점과 화살표 방향을 연결해요.", gate: "수직선 관문", tone: "blue", theory: "기준값을 포함하면 채워진 점(●), 포함하지 않으면 빈 점(○)으로 나타내요.", questions: [{ prompt: "‘40 초과’를 수직선으로 나타낼 때 알맞은 설명은 무엇일까요?", options: ["40에서 채워진 점, 왼쪽 방향", "40에서 빈 점, 왼쪽 방향", "40에서 채워진 점, 오른쪽 방향", "40에서 빈 점, 오른쪽 방향"], answers: ["40에서 빈 점, 오른쪽 방향"], explanation: "초과는 기준값을 포함하지 않으므로 빈 점, 기준값보다 큰 쪽이므로 오른쪽 방향이에요.", hint: "초과는 빈 점이고, 큰 수가 있는 쪽으로 가요." }] },
  { id: 5, title: "부족하지 않은 창고", place: "올림", concept: "부족하지 않게", summary: "모두 담거나 부족하지 않게 준비할 때 올림해요.", gate: "창고 관문", tone: "orange", theory: "올림은 구하려는 자리 아래 수를 올려서 나타내요. 필요한 양보다 부족하지 않아야 할 때 사용해요.", questions: [{ prompt: "한 상자에 사과 10개씩 담습니다. 사과 83개를 모두 담으려면 상자는 몇 개 필요할까요?", options: ["8개", "9개", "10개", "80개"], answers: ["9개"], explanation: "83개를 모두 담아야 하므로 부족하지 않게 올림해요. 10개 상자 9개가 필요해요.", hint: "8상자는 80개만 담을 수 있어요. 모두 담으려면 하나가 더 필요해요." }] },
  { id: 6, title: "남김없는 작업장", place: "버림", concept: "완전한 묶음", summary: "완전하게 만들 수 있는 묶음만 생각할 때 버림해요.", gate: "작업장 관문", tone: "orange", theory: "버림은 구하려는 자리 아래 수를 버려서 나타내요. 완전한 묶음의 수만 필요할 때 사용해요.", questions: [{ prompt: "764cm의 리본으로 10cm 묶음을 최대 몇 개 만들 수 있을까요?", options: ["7개", "76개", "77개", "760개"], answers: ["76개"], explanation: "10cm 묶음은 76개를 완전히 만들 수 있어요. 남은 4cm는 완전한 묶음이 아니므로 버려요.", hint: "10cm씩 묶을 수 있는 완전한 묶음만 세어 보세요." }] },
  { id: 7, title: "가장 가까운 광장", place: "반올림", concept: "가장 가까운 값", summary: "가장 가까운 값으로 나타낼 때 반올림해요.", gate: "광장 관문", tone: "mint", theory: "반올림은 바로 아래 자리 숫자가 5 이상이면 올리고, 5보다 작으면 버려요.", questions: [{ prompt: "3,650을 천의 자리까지 반올림한 수를 고르세요.", options: ["3,000", "3,600", "4,000", "3,700"], answers: ["4,000"], explanation: "천의 자리 바로 아래인 백의 자리 숫자가 6이에요. 5 이상이므로 올려서 4,000이 돼요.", hint: "천의 자리 바로 아래인 백의 자리 6을 보세요." }] },
  { id: 8, title: "시간의 지도", place: "종합 관문", concept: "방법 선택", summary: "상황의 목적에 따라 올림·버림·반올림을 선택해요.", gate: "시간의 지도", tone: "purple", theory: "부족하면 안 되면 올림, 완전한 묶음이면 버림, 가장 가까운 값이면 반올림이에요.", questions: [{ prompt: "학급 학생 287명의 대략적인 인원을 백의 자리까지 나타내려고 합니다. 어떤 방법이 알맞을까요?", options: ["올림", "버림", "반올림", "이상"], answers: ["반올림"], explanation: "대략적인 인원을 가장 가까운 값으로 나타내므로 반올림이 알맞아요. 287명은 약 300명이에요.", hint: "가장 가까운 값을 구할 때 사용하는 방법을 생각해 보세요." }] },
];

const emptyRecords = (): Records => Object.fromEntries(quests.map((quest) => [quest.id, { accuracy: 0, attempts: 0, hints: 0, completed: false }])) as Records;
const formatTime = (seconds: number) => `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
const noteKey = (questId: number, questionIndex: number) => `${questId}-${questionIndex}`;
const normalizeAnswer = (value: string) => value.replace(/[\s,]/g, "").trim();
const isAnswerCorrect = (answers: string[], selected: string[]) => selected.length > 0 && answers.length === selected.length && answers.every((answer) => selected.some((value) => normalizeAnswer(value) === normalizeAnswer(answer)));
const buildMiniReviewQueue = (notes: WrongNote[], questId: number): MiniReviewItem[] => {
  const seen = new Set<string>();
  const remember = (question: QuestQuestion, source: MiniReviewItem["source"]): MiniReviewItem | null => {
    if (seen.has(question.prompt)) return null;
    seen.add(question.prompt);
    return { ...question, questId, source };
  };
  const fromNotes = notes.filter((note) => note.questId === questId).sort((a, b) => b.wrongCount - a.wrongCount).map((note) => remember(note, "오답 확인")).filter((item): item is MiniReviewItem => Boolean(item));
  const reinforcement = quests[questId - 1].questions.map((question) => remember(question, "약점 강화")).filter((item): item is MiniReviewItem => Boolean(item));
  return [...fromNotes, ...reinforcement].slice(0, 5);
};

function QuestEmblem({ tone, done = false, locked = false }: { tone: Quest["tone"]; done?: boolean; locked?: boolean }) {
  return <div className={`quest-emblem quest-emblem--${tone} ${done ? "quest-emblem--done" : ""} ${locked ? "quest-emblem--locked" : ""}`}>{locked ? <Lock size={20} /> : done ? <Check size={22} /> : <Target size={21} />}</div>;
}

export default function Home() {
  const [records, setRecords] = useState<Records>(() => emptyRecords());
  const [wrongNotes, setWrongNotes] = useState<WrongNote[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [screen, setScreen] = useState<Screen>("map");
  const [activeQuestId, setActiveQuestId] = useState(1);
  const [activeNoteId, setActiveNoteId] = useState<string | null>(null);
  const [noteFilter, setNoteFilter] = useState<NoteFilter>("all");
  const [reviewQueue, setReviewQueue] = useState<string[]>([]);
  const [questionIndex, setQuestionIndex] = useState(0);
  const [selected, setSelected] = useState<string[]>([]);
  const [submitted, setSubmitted] = useState(false);
  const [correct, setCorrect] = useState(false);
  const [attempts, setAttempts] = useState(0);
  const [correctCount, setCorrectCount] = useState(0);
  const [hints, setHints] = useState(0);
  const [startedAt, setStartedAt] = useState<number | null>(null);
  const [elapsed, setElapsed] = useState(0);
  const [lastResult, setLastResult] = useState<RecordValue | null>(null);
  const [showHint, setShowHint] = useState(false);
  const [showSolvedStamp, setShowSolvedStamp] = useState(false);
  const [unlockSequence, setUnlockSequence] = useState<UnlockSequence | null>(null);
  const [miniQueue, setMiniQueue] = useState<MiniReviewItem[]>([]);
  const [miniIndex, setMiniIndex] = useState(0);
  const [miniCorrectCount, setMiniCorrectCount] = useState(0);
  const [miniAttempts, setMiniAttempts] = useState(0);
  const [miniWeakQuestId, setMiniWeakQuestId] = useState<number | null>(null);

  useEffect(() => { try { const savedRecords = window.localStorage.getItem("boundary-quest-records"); const savedNotes = window.localStorage.getItem("boundary-wrong-notes"); if (savedRecords) setRecords({ ...emptyRecords(), ...JSON.parse(savedRecords) }); if (savedNotes) setWrongNotes(JSON.parse(savedNotes)); } finally { setLoaded(true); } }, []);
  useEffect(() => { if (loaded) { window.localStorage.setItem("boundary-quest-records", JSON.stringify(records)); window.localStorage.setItem("boundary-wrong-notes", JSON.stringify(wrongNotes)); } }, [records, wrongNotes, loaded]);
  useEffect(() => { if (screen !== "play" || !startedAt) return; const interval = window.setInterval(() => setElapsed(Math.floor((Date.now() - startedAt) / 1000)), 1000); return () => window.clearInterval(interval); }, [screen, startedAt]);

  const quest = quests[activeQuestId - 1];
  const question = quest.questions[questionIndex];
  const boss = bossChallenges[activeQuestId];
  const completedCount = quests.filter((item) => records[item.id]?.completed).length;
  const achievementCount = completedCount + (completedCount === quests.length ? 1 : 0);
  const unlocked = (id: number) => id === 1 || records[id - 1]?.completed;
  const activeRecord = records[activeQuestId] ?? emptyRecords()[activeQuestId];
  const currentCorrect = isAnswerCorrect(question.answers, selected);

  const saveWrongNote = (selectedAnswer: string[]) => setWrongNotes((current) => { const id = noteKey(activeQuestId, questionIndex); const old = current.find((note) => note.id === id); const next: WrongNote = { ...question, id, questId: activeQuestId, questionIndex, selected: selectedAnswer, wrongCount: (old?.wrongCount ?? 0) + 1, lastWrongAt: Date.now() }; return old ? current.map((note) => note.id === id ? next : note) : [...current, next]; });
  const clearWrongNote = (questId: number, index: number) => setWrongNotes((current) => current.filter((note) => note.id !== noteKey(questId, index)));

  const openQuest = (id: number) => { if (!unlocked(id)) return; setActiveQuestId(id); setScreen("brief"); setQuestionIndex(0); setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); };
  const startQuest = () => { const now = Date.now(); setStartedAt(now); setElapsed(0); setAttempts(0); setCorrectCount(0); setHints(0); setQuestionIndex(0); setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); setScreen("play"); };
  const submit = () => { if (selected.length === 0) return; setAttempts((count) => count + 1); setCorrect(currentCorrect); setSubmitted(true); if (currentCorrect) { setCorrectCount((count) => count + 1); clearWrongNote(activeQuestId, questionIndex); } else saveWrongNote(selected); };
  const retry = () => { setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); };
  const nextQuestion = () => { if (questionIndex < quest.questions.length - 1) { setQuestionIndex((index) => index + 1); retry(); } else { retry(); setScreen("boss"); } };
  const submitBoss = () => { if (!selected.length) return; const bossCorrect = isAnswerCorrect(boss.question.answers, selected); setAttempts((count) => count + 1); setCorrect(bossCorrect); setSubmitted(true); if (bossCorrect) setCorrectCount((count) => count + 1); };
  const finishQuest = () => { const finalSeconds = startedAt ? Math.floor((Date.now() - startedAt) / 1000) : elapsed; const totalQuestions = quest.questions.length + 1; const accuracy = Math.round((totalQuestions / Math.max(attempts, totalQuestions)) * 100); const previous = records[activeQuestId] ?? emptyRecords()[activeQuestId]; const nextRecord: RecordValue = { best: previous.best ? Math.min(previous.best, finalSeconds) : finalSeconds, accuracy, attempts, hints, completed: true, bossCleared: true, rewardTitle: boss.rewardTitle }; setRecords((current) => ({ ...current, [activeQuestId]: nextRecord })); setLastResult(nextRecord); if (activeQuestId === quests.length) { setScreen("ending"); } else { setUnlockSequence({ from: activeQuestId, next: activeQuestId + 1, result: nextRecord }); setScreen("unlock"); } };
  const toggleOption = (option: string) => { if (submitted) return; if (question.multiple) setSelected((current) => current.includes(option) ? current.filter((item) => item !== option) : [...current, option]); else setSelected([option]); };
  const openNote = (note: WrongNote) => { setReviewQueue([]); setActiveNoteId(note.id); setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); setScreen("note-play"); };
  const reviewWeakConcept = (questId: number) => { setActiveQuestId(questId); setQuestionIndex(0); setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); setScreen("brief"); };
  const filteredNotes = noteFilter === "all" ? wrongNotes : wrongNotes.filter((note) => note.questId === noteFilter);
  const startAllReview = () => { if (!filteredNotes.length) return; const queue = filteredNotes.map((note) => note.id); setReviewQueue(queue); setActiveNoteId(queue[0]); setSelected([]); setSubmitted(false); setCorrect(false); setShowSolvedStamp(false); setScreen("note-play"); };
  const startMiniReview = () => { if (!wrongNotes.length) return; const stats = Object.values(wrongNotes.reduce<Record<number, { questId: number; count: number }>>((result, note) => { result[note.questId] = { questId: note.questId, count: (result[note.questId]?.count ?? 0) + note.wrongCount }; return result; }, {})).sort((a, b) => b.count - a.count); const weakQuestId = stats[0]?.questId; if (!weakQuestId) return; const queue = buildMiniReviewQueue(wrongNotes, weakQuestId); if (queue.length < 5) return; setActiveQuestId(weakQuestId); setMiniWeakQuestId(weakQuestId); setMiniQueue(queue); setMiniIndex(0); setMiniCorrectCount(0); setMiniAttempts(0); setSelected([]); setSubmitted(false); setCorrect(false); setShowHint(false); setScreen("mini-review"); };
  const submitMiniReview = () => { const item = miniQueue[miniIndex]; if (!item || !selected.length) return; const itemCorrect = isAnswerCorrect(item.answers, selected); setMiniAttempts((count) => count + 1); setCorrect(itemCorrect); setSubmitted(true); if (itemCorrect) setMiniCorrectCount((count) => count + 1); };
  const nextMiniReview = () => { if (miniIndex < miniQueue.length - 1) { setMiniIndex((index) => index + 1); retry(); } else setScreen("mini-result"); };
  const playSolvedFeedback = () => { if ("vibrate" in navigator) navigator.vibrate?.([35, 22, 65]); try { const audio = new AudioContext(); const now = audio.currentTime; [660, 880].forEach((frequency, index) => { const oscillator = audio.createOscillator(); const gain = audio.createGain(); oscillator.type = "triangle"; oscillator.frequency.setValueAtTime(frequency, now + index * 0.11); gain.gain.setValueAtTime(0.0001, now + index * 0.11); gain.gain.exponentialRampToValueAtTime(0.075, now + index * 0.11 + 0.015); gain.gain.exponentialRampToValueAtTime(0.0001, now + index * 0.11 + 0.22); oscillator.connect(gain).connect(audio.destination); oscillator.start(now + index * 0.11); oscillator.stop(now + index * 0.11 + 0.24); }); window.setTimeout(() => audio.close(), 500); } catch { /* browser sound is optional */ } };
  const finishNote = (note: WrongNote) => { clearWrongNote(note.questId, note.questionIndex); setCorrect(true); setSubmitted(true); setShowSolvedStamp(true); playSolvedFeedback(); window.setTimeout(() => { setShowSolvedStamp(false); const remaining = reviewQueue.filter((id) => id !== note.id); if (remaining.length) { setReviewQueue(remaining); setActiveNoteId(remaining[0]); setSelected([]); setSubmitted(false); setCorrect(false); } else { setReviewQueue([]); setScreen("notes"); } }, 1250); };

  if (screen === "brief") return <BriefScreen quest={quest} record={activeRecord} noteCount={wrongNotes.length} onBack={() => setScreen("map")} onNotes={() => setScreen("notes")} onStart={startQuest} />;
  if (screen === "play") return <PlayScreen quest={quest} question={question} questionIndex={questionIndex} selected={selected} submitted={submitted} correct={correct} elapsed={elapsed} attempts={attempts} hints={hints} showHint={showHint} noteCount={wrongNotes.length} onBack={() => setScreen("map")} onNotes={() => setScreen("notes")} onToggle={toggleOption} onSubmit={submit} onRetry={retry} onNext={nextQuestion} onHint={() => { setShowHint((value) => !value); if (!showHint) setHints((value) => value + 1); }} />;
  if (screen === "boss") return <BossScreen quest={quest} boss={boss} selected={selected} submitted={submitted} correct={correct} elapsed={elapsed} attempts={attempts} onBack={() => setScreen("map")} onToggle={toggleOption} onSubmit={submitBoss} onRetry={retry} onClear={() => { retry(); setScreen("boss-clear"); }} />;
  if (screen === "boss-clear") return <BossClearScreen quest={quest} boss={boss} onContinue={finishQuest} onMap={() => setScreen("map")} />;
  if (screen === "unlock" && unlockSequence) return <UnlockScreen sequence={unlockSequence} noteCount={wrongNotes.length} onMap={() => { setActiveQuestId(unlockSequence.next ?? unlockSequence.from); setUnlockSequence(null); setScreen("map"); }} onNext={() => { if (!unlockSequence.next) { setUnlockSequence(null); setScreen("map"); return; } setActiveQuestId(unlockSequence.next); setUnlockSequence(null); setScreen("brief"); }} onAchievements={() => setScreen("achievements")} />;
  if (screen === "ending") return <FinalEndingScreen records={records} noteCount={wrongNotes.length} onMap={() => setScreen("map")} onAchievements={() => setScreen("achievements")} />;
  if (screen === "achievements") return <AchievementScreen records={records} noteCount={wrongNotes.length} onMap={() => setScreen("map")} />;
  if (screen === "result" && lastResult) return <ResultScreen quest={quest} result={lastResult} noteCount={wrongNotes.length} onMap={() => { const nextId = Math.min(quests.length, activeQuestId + 1); setActiveQuestId(nextId); setScreen("map"); }} onNotes={() => setScreen("notes")} onNext={() => { const nextId = Math.min(quests.length, activeQuestId + 1); setActiveQuestId(nextId); setScreen(unlocked(nextId) ? "brief" : "map"); }} />;
  if (screen === "notes") return <MistakeBookScreen notes={wrongNotes} filter={noteFilter} onFilter={setNoteFilter} onMap={() => setScreen("map")} onPractice={openNote} onAllPractice={startAllReview} onMiniReview={startMiniReview} onReviewConcept={reviewWeakConcept} />;
  if (screen === "note-play") { const note = wrongNotes.find((item) => item.id === activeNoteId); if (note) return <MistakePracticeScreen note={note} selected={selected} submitted={submitted} correct={correct} showSolvedStamp={showSolvedStamp} onBack={() => setScreen("notes")} onToggle={(option) => { if (!submitted) setSelected((current) => note.multiple ? current.includes(option) ? current.filter((item) => item !== option) : [...current, option] : [option]); }} onSubmit={() => { if (isAnswerCorrect(note.answers, selected)) finishNote(note); else { setCorrect(false); setSubmitted(true); saveNoteRetry(note, selected, setWrongNotes); } }} onRetry={retry} />; }
  if (screen === "mini-review" && miniQueue[miniIndex]) return <MiniReviewScreen queue={miniQueue} weakQuestId={miniWeakQuestId ?? activeQuestId} index={miniIndex} selected={selected} submitted={submitted} correct={correct} attempts={miniAttempts} onBack={() => setScreen("notes")} onToggle={toggleOption} onSubmit={submitMiniReview} onRetry={retry} onNext={nextMiniReview} />;
  if (screen === "mini-result" && miniWeakQuestId) return <MiniReviewResultScreen quest={quests[miniWeakQuestId - 1]} correctCount={miniCorrectCount} attempts={miniAttempts} onNotes={() => setScreen("notes")} onRestart={startMiniReview} />;
  return <MapScreen records={records} completedCount={completedCount} achievementCount={achievementCount} activeQuestId={activeQuestId} wrongCount={wrongNotes.length} onOpen={openQuest} onNotes={() => setScreen("notes")} onAchievements={() => setScreen("achievements")} />;
}

function saveNoteRetry(note: WrongNote, selectedAnswer: string[], setWrongNotes: React.Dispatch<React.SetStateAction<WrongNote[]>>) { setWrongNotes((current) => current.map((item) => item.id === note.id ? { ...item, selected: selectedAnswer, wrongCount: item.wrongCount + 1, lastWrongAt: Date.now() } : item)); }

function Header({ onMap, onNotes, onAchievements, noteCount = 0, title = "경계의 성", focus = "01 · 단원 도입" }: { onMap?: () => void; onNotes?: () => void; onAchievements?: () => void; noteCount?: number; title?: string; focus?: string }) {
  return <header className="quest-header"><button type="button" className="quest-brand" onClick={onMap}><span className="quest-brand__mark"><ShieldCheck size={19} /><i>문</i></span><span><small>1단원 · 수의 범위와 어림하기</small><strong>{title}</strong></span></button><div className="quest-header__center"><span>지금 열 관문</span><ChevronRight size={14} /><b>{focus}</b></div><div className="quest-header__actions">{onAchievements && <button type="button" className="achievement-header-button" onClick={onAchievements}><Trophy size={16} /> 업적</button>}{onNotes && <button type="button" className="notes-header-button" onClick={onNotes}><BookOpenCheck size={16} /> 오답 노트 <b>{noteCount}</b></button>}<div className="quest-header__profile"><span>나의 기록</span><strong>J</strong></div></div></header>;
}

/** Design: neo-brutalist badge vault — ink outline, offset shadow, primary color blocks, completion as a collectible stamp. */
function AchievementScreen({ records, noteCount, onMap }: { records: Records; noteCount: number; onMap: () => void }) {
  const completed = quests.filter((item) => records[item.id]?.completed);
  const totalBest = completed.reduce((total, item) => total + (records[item.id].best ?? 0), 0);
  const averageAccuracy = completed.length ? Math.round(completed.reduce((total, item) => total + records[item.id].accuracy, 0) / completed.length) : 0;
  const fullClear = completed.length === quests.length;
  return <main className="quest-app">
    <Header onMap={onMap} title="업적 보관소" focus={`${completed.length} / ${quests.length} 관문 통과`} />
    <section className="achievement-page">
      <div className="achievement-hero"><div><p className="quest-kicker">획득한 관문 인장</p><h1>배지를 모아<br /><em>성의 기록을 남겨요.</em></h1><p>각 관문을 통과하면 인장이 보관됩니다. 최고 기록과 정확도를 확인하고, 비어 있는 인장도 다음 도전에서 채워 보세요.</p><div className="achievement-summary"><span><Trophy size={18} /><b>{completed.length}</b> / {quests.length} 획득</span><span><Target size={18} /><b>{averageAccuracy}%</b> 평균 정확도</span><span><Clock3 size={18} /><b>{completed.length ? formatTime(totalBest) : "--:--"}</b> 최고 기록 합계</span></div></div><div className={`achievement-hero__badge ${fullClear ? "achievement-hero__badge--crowned" : ""}`}><img src="/manus-storage/boundary-badge-set_6a5ef52b.png" alt="경계의 성 관문 통과 배지" /><span>{fullClear ? "성 복구 업적" : "다음 배지를 향해"}</span></div></div>
      <div className="achievement-grid">{quests.map((item) => {
        const record = records[item.id];
        const earned = record?.completed;
        return <article key={item.id} className={`achievement-card achievement-card--${item.tone} ${earned ? "achievement-card--earned" : "achievement-card--locked"}`}><div className="achievement-card__seal"><QuestEmblem tone={item.tone} done={earned} locked={!earned} /></div><div className="achievement-card__title"><span>관문 {String(item.id).padStart(2, "0")}</span><h2>{earned ? item.title : "봉인된 인장"}</h2><p>{earned ? item.concept : "앞 관문을 통과하면 이 배지가 열립니다."}</p></div><div className="achievement-card__record">{earned ? <div className="achievement-card__record-list"><span><Crown size={14} /> 칭호 <b>{record.rewardTitle ?? "관문 개척자"}</b></span><span><Clock3 size={14} /> 최고 <b>{formatTime(record.best ?? 0)}</b></span><span><Target size={14} /> 정확도 <b>{record.accuracy}%</b></span><span><RotateCcw size={14} /> 최근 시도 <b>{record.attempts}회</b></span></div> : <span className="achievement-card__empty"><Lock size={14} /> 미획득</span>}</div><i className="achievement-card__stamp">{earned ? "획득" : "봉인"}</i></article>;
      })}</div>
      <div className="achievement-footer"><div><Crown size={22} /><span><b>{fullClear ? "경계의 성 복구 완료" : `마지막 업적까지 ${quests.length - completed.length}개 관문 남음`}</b><small>{noteCount ? `오답 노트에 ${noteCount}문제가 있어요. 복습 후 더 단단하게 통과해 보세요.` : "오답 노트가 비어 있어요. 정확한 학습 기록입니다."}</small></span></div><button type="button" className="map-button" onClick={onMap}>퀘스트 지도로 <ArrowRight size={17} /></button></div>
    </section>
  </main>;
}

/** Design: a staged, cinematic brutalist finale that preserves the app's stamp-and-print language over game art. */
function FinalEndingScreen({ records, noteCount, onMap, onAchievements }: { records: Records; noteCount: number; onMap: () => void; onAchievements: () => void }) {
  const [phase, setPhase] = useState(0);
  const completed = quests.filter((item) => records[item.id]?.completed);
  const totalBest = completed.reduce((total, item) => total + (records[item.id].best ?? 0), 0);
  const averageAccuracy = completed.length ? Math.round(completed.reduce((total, item) => total + records[item.id].accuracy, 0) / completed.length) : 0;
  useEffect(() => { const timers = [window.setTimeout(() => setPhase(1), 480), window.setTimeout(() => setPhase(2), 1280), window.setTimeout(() => setPhase(3), 2180)]; return () => timers.forEach((timer) => window.clearTimeout(timer)); }, []);
  const confetti = Array.from({ length: 38 }, (_, index) => ({ id: index, x: (index * 37) % 100, delay: (index % 9) * 0.13, duration: 1.7 + (index % 5) * 0.22, rotate: (index * 53) % 360 }));
  return <main className="quest-app"><Header onMap={phase >= 3 ? onMap : undefined} onAchievements={phase >= 3 ? onAchievements : undefined} noteCount={noteCount} title="경계의 성" focus="11관문 · 최종 통과" /><section className={`final-ending final-ending--phase-${phase}`}><div className="final-ending__art" aria-hidden="true"><img src="/manus-storage/boundary-castle-restored-ending_1af1796c.jpg" alt="" /></div><div className="final-ending__veil" /><div className="final-ending__confetti" aria-hidden="true">{confetti.map((piece) => <i key={piece.id} style={{ "--x": `${piece.x}%`, "--delay": `${piece.delay}s`, "--duration": `${piece.duration}s`, "--spin": `${piece.rotate}deg` } as CSSProperties} />)}</div><div className="final-ending__content"><p className="quest-kicker">최종 관문 통과 · 11 / 11</p><div className="final-ending__seal"><ShieldCheck size={46} /><span>전체 통과</span></div><h1>경계의 성이<br /><em>다시 빛납니다.</em></h1><p>11개의 관문과 {quests.reduce((total, item) => total + item.questions.length, 0)}문항을 끝까지 탐험했어요. 숫자의 범위와 어림하기 지도를 완성했습니다.</p><div className="final-ending__records"><span><Trophy size={18} /><b>{completed.length}</b>개 관문</span><span><Target size={18} /><b>{averageAccuracy}%</b> 평균 정확도</span><span><Clock3 size={18} /><b>{formatTime(totalBest)}</b> 최고 기록 합계</span></div><div className="final-ending__actions"><button type="button" className="map-button" onClick={onAchievements} disabled={phase < 3}>업적 보관소 <Trophy size={17} /></button><button type="button" className="next-quest final-ending__map-button" onClick={onMap} disabled={phase < 3}>복구된 지도 보기 <ArrowRight size={17} /></button></div></div></section></main>;
}

function MapScreen({ records, completedCount, achievementCount, activeQuestId, wrongCount, onOpen, onNotes, onAchievements }: { records: Records; completedCount: number; achievementCount: number; activeQuestId: number; wrongCount: number; onOpen: (id: number) => void; onNotes: () => void; onAchievements: () => void }) {
  const activeQuest = quests[activeQuestId - 1];
  const totalQuestions = quests.reduce((total, item) => total + item.questions.length, 0);
  const point = (index: number) => {
    const row = Math.floor(index / 4);
    const column = index % 4;
    const xPositions = row % 2 === 0 ? [16, 38, 60, 82] : [82, 60, 38, 16];
    return { x: xPositions[column], y: 21 + row * 28 };
  };
  return <main className="quest-app"><Header onNotes={onNotes} onAchievements={onAchievements} noteCount={wrongCount} focus={`${String(activeQuest.id).padStart(2, "0")} · ${activeQuest.place}`} /><section className="map-page"><div className="map-intro"><div className="map-title-block"><p className="quest-kicker">지도서 기반 · 11개 차시 · 총 {totalQuestions}문항</p><h1>경계의 성을<br /><em>되찾아 주세요.</em></h1><p>각 관문은 {activeQuest.questions.length}문항으로 구성됩니다.<br />정확하게 통과하면 다음 길이 열립니다.</p></div><section className="map-focus" aria-label="현재 학습 관문"><span>지금 배울 개념</span><strong>{activeQuest.concept}</strong><p><b>관문 {String(activeQuest.id).padStart(2, "0")}</b> · {activeQuest.title}</p><button type="button" onClick={() => onOpen(activeQuest.id)}>관문 도전 <ArrowRight size={16} /></button></section><div className="map-progress"><div className="map-progress__icon"><Crown size={23} /></div><div><span>나의 관문 기록</span><strong>{completedCount} <small>/ {quests.length} 통과</small></strong><i><b style={{ width: `${(completedCount / quests.length) * 100}%` }} /></i></div><button type="button" className="map-achievement-link" onClick={onAchievements}><Trophy size={15} /> 업적 {achievementCount}</button></div></div><div className="quest-map"><div className="map-route" /><svg className="map-route-svg" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">{quests.slice(0, -1).map((item, index) => { const from = point(index); const to = point(index + 1); return <line key={item.id} className={records[item.id]?.completed ? "map-route-line map-route-line--lit" : "map-route-line"} x1={from.x} y1={from.y} x2={to.x} y2={to.y} />; })}</svg>{quests.map((item, index) => { const done = records[item.id]?.completed; const locked = !((item.id === 1) || records[item.id - 1]?.completed); const current = activeQuestId === item.id && !done; const stamp = current ? "도전" : done ? "통과" : locked ? "봉인" : "다음"; return <button type="button" key={item.id} className={`quest-node quest-node--${item.tone} ${done ? "quest-node--done" : ""} ${locked ? "quest-node--locked" : ""} ${current ? "quest-node--current" : ""}`} style={{ "--node-x": `${point(index).x}%`, "--node-y": `${point(index).y}%` } as CSSProperties} onClick={() => onOpen(item.id)}><QuestEmblem tone={item.tone} done={done} locked={locked} /><span className="quest-node__text"><b>{String(item.id).padStart(2, "0")} · {item.place}</b><strong>{item.title}</strong><small>{done ? `최고 ${formatTime(records[item.id].best ?? 0)}` : locked ? "앞 관문을 통과하면 열림" : `${item.questions.length}문항 · ${item.concept}`}</small></span><span className={`node-stamp node-stamp--${current ? "current" : done ? "done" : locked ? "locked" : "next"}`}>{stamp}</span>{current && <span className="current-pill">지금 풀기</span>}</button>; })}<div className="map-landmark map-landmark--start"><span>출발</span><ShieldCheck size={18} /></div><div className={`map-landmark map-landmark--finish ${completedCount === quests.length ? "map-landmark--restored" : ""}`}><Trophy size={24} /><span>{completedCount === quests.length ? "성 복구 완료" : "종합 관문"}</span></div></div><div className="map-footer"><span><Clock3 size={15} /> 차시별 최고 기록이 남아요.</span><span><Target size={15} /> 정확하게 푸는 것이 먼저</span></div></section></main>;
}

function BriefScreen({ quest, record, noteCount, onBack, onNotes, onStart }: { quest: Quest; record: RecordValue; noteCount: number; onBack: () => void; onNotes: () => void; onStart: () => void }) {
  return <main className="quest-app"><Header onMap={onBack} onNotes={onNotes} noteCount={noteCount} focus={`${String(quest.id).padStart(2, "0")} · ${quest.place}`} /><section className="brief-page"><div className="brief-visual"><div className={`brief-orb brief-orb--${quest.tone}`}><QuestEmblem tone={quest.tone} /></div><div className="brief-path"><i /><i /><i /></div><div className="brief-landmark"><Flag size={23} /></div><span className="brief-label brief-label--a">{quest.place}</span><span className="brief-label brief-label--b">관문 {String(quest.id).padStart(2, "0")}</span></div><div className="brief-content"><button type="button" className="back-link" onClick={onBack}><ArrowLeft size={15} /> 퀘스트 맵으로</button><p className="quest-kicker">관문 {String(quest.id).padStart(2, "0")} · {quest.gate}</p><h1>{quest.title}</h1><p className="brief-summary">{quest.summary}</p><div className="brief-theory"><BookOpen size={19} /><div><span>이번 관문에서 알아야 할 것</span><strong>{quest.concept}</strong><p>{quest.theory}</p></div></div><div className="brief-rule"><Lightbulb size={17} /><span>{quest.questions.length}문항을 정확하게 통과하면 다음 관문의 봉인이 풀립니다.</span></div><button type="button" className="start-quest" onClick={onStart}>관문 도전 시작 <ArrowRight size={18} /></button>{record.completed && <div className="previous-record"><span>지난 기록</span><b>{formatTime(record.last ?? 0)}</b><small>최고 {formatTime(record.best ?? 0)} · 정확도 {record.accuracy}%</small></div>}</div></section></main>;
}

function PlayScreen({ quest, question, questionIndex, selected, submitted, correct, elapsed, attempts, hints, showHint, noteCount, onBack, onNotes, onToggle, onSubmit, onRetry, onNext, onHint }: { quest: Quest; question: QuestQuestion; questionIndex: number; selected: string[]; submitted: boolean; correct: boolean; elapsed: number; attempts: number; hints: number; showHint: boolean; noteCount: number; onBack: () => void; onNotes: () => void; onToggle: (option: string) => void; onSubmit: () => void; onRetry: () => void; onNext: () => void; onHint: () => void }) {
  return <main className="quest-app"><Header onMap={onBack} onNotes={onNotes} noteCount={noteCount} title={quest.title} focus={`${String(quest.id).padStart(2, "0")} · ${question.category} ${questionIndex + 1}/${quest.questions.length}`} /><div className="play-layout"><aside className="play-rail"><div className={`rail-seal rail-seal--${quest.tone}`}><QuestEmblem tone={quest.tone} /></div><p className="quest-kicker">차시 {String(quest.id).padStart(2, "0")}</p><h1>{quest.place}<br /><em>관문</em></h1><p>{quest.concept}</p><div className="rail-time"><Clock3 size={16} /><span>경과 시간</span><strong>{formatTime(elapsed)}</strong></div><div className="rail-steps">{quest.questions.map((item, index) => <div key={index} className={index < questionIndex ? "rail-step rail-step--done" : index === questionIndex ? "rail-step rail-step--current" : "rail-step"}><span>{index < questionIndex ? <Check size={12} /> : index + 1}</span><b>{index === questionIndex ? item.category : index < questionIndex ? "통과" : item.category}</b></div>)}</div><div className="rail-record"><span>이번 시도</span><strong>{attempts}회</strong><small>힌트 {hints}회</small></div></aside><section className="play-main"><div className="play-top"><div><p className="quest-kicker">{quest.gate}</p><h2>관문을 하나씩 통과하세요.</h2></div><div className="play-counter"><span>{questionIndex + 1}</span><small>/ {quest.questions.length}</small></div></div><div className="question-sheet"><div className="sheet-header"><span className={`quest-tag quest-tag--${quest.tone}`}>{quest.concept}</span><span className="sheet-status">{question.category} · 문제 {questionIndex + 1}</span></div><h3>{question.prompt}</h3>{question.multiple && <p className="multi-note">정답을 모두 선택하세요.</p>}{question.input ? <label className="direct-answer"><span>숫자로 답을 입력하세요</span><input type="text" inputMode="decimal" value={selected[0] ?? ""} disabled={submitted} onChange={(event) => onToggle(event.target.value)} placeholder="정답 입력" aria-label="정답 입력" /></label> : <div className="quest-options">{question.options.map((option, index) => <button type="button" key={option} disabled={submitted} className={`quest-option ${selected.includes(option) ? "quest-option--selected" : ""} ${submitted && question.answers.includes(option) ? "quest-option--correct" : ""} ${submitted && selected.includes(option) && !question.answers.includes(option) ? "quest-option--wrong" : ""}`} onClick={() => onToggle(option)}><span>{String.fromCharCode(65 + index)}</span><strong>{option}</strong>{selected.includes(option) && !submitted && <Check size={16} />}{submitted && question.answers.includes(option) && <Check size={16} />}{submitted && selected.includes(option) && !question.answers.includes(option) && <X size={16} />}</button>)}</div>}<div className="sheet-actions"><button type="button" className="hint-action" onClick={onHint}><Lightbulb size={16} /> 힌트 {hints > 0 ? `${hints}회` : "보기"}</button>{!submitted ? <button type="button" className="answer-action" onClick={onSubmit} disabled={!selected.length}>정답 제출 <ArrowRight size={16} /></button> : correct ? <button type="button" className="answer-action answer-action--success" onClick={onNext}>{questionIndex === quest.questions.length - 1 ? "보스전 입장" : "다음 문제"} <ArrowRight size={16} /></button> : <button type="button" className="retry-action" onClick={onRetry}><RotateCcw size={15} /> 다시 풀기</button>}</div>{showHint && <div className="quest-hint"><Lightbulb size={16} /><span><b>힌트</b>{question.hint}</span></div>}{submitted && <div className={correct ? "quest-feedback quest-feedback--success" : "quest-feedback quest-feedback--wrong"}><span>{correct ? <Check size={18} /> : <X size={18} />}</span><div><strong>{correct ? "관문에 빛이 켜졌어요." : "아직 이 문은 열리지 않아요."}</strong><p>{question.explanation}</p></div></div>}</div><div className="play-bottom"><span><ShieldCheck size={15} /> {quest.questions.length}문항 뒤에는 보스전이 기다리고 있어요.</span><span>오답은 오답 노트에 저장됨</span></div></section></div></main>;
}

/** Design: the boss gate is a rare, high-stakes one-question poster, not another ordinary quiz card. */
function BossScreen({ quest, boss, selected, submitted, correct, elapsed, attempts, onBack, onToggle, onSubmit, onRetry, onClear }: { quest: Quest; boss: BossChallenge; selected: string[]; submitted: boolean; correct: boolean; elapsed: number; attempts: number; onBack: () => void; onToggle: (option: string) => void; onSubmit: () => void; onRetry: () => void; onClear: () => void }) {
  const question = boss.question;
  return <main className="quest-app"><Header onMap={onBack} title="보스 관문" focus={`${String(quest.id).padStart(2, "0")} · ${boss.title}`} /><section className={`boss-page boss-page--${quest.tone}`}><div className="boss-signal"><div className="boss-signal__seal"><Crown size={32} /></div><p className="quest-kicker">최종 한 문제 · 보스전</p><h1>{boss.title}<br /><em>마지막 봉인을 풀어라.</em></h1><p>{boss.intro}</p><div className="boss-signal__stats"><span><Clock3 size={15} /> {formatTime(elapsed)}</span><span><Target size={15} /> 시도 {attempts}회</span><span><Trophy size={15} /> 보상: {boss.rewardTitle}</span></div></div><div className="boss-sheet"><div className="boss-sheet__bar"><span>보스 문제</span><b>관문 {String(quest.id).padStart(2, "0")} · {quest.concept}</b></div><h2>{question.prompt}</h2>{question.multiple && <p className="multi-note">정답을 모두 선택하세요.</p>}<div className="quest-options boss-options">{question.options.map((option, index) => <button type="button" key={option} disabled={submitted} className={`quest-option ${selected.includes(option) ? "quest-option--selected" : ""} ${submitted && question.answers.includes(option) ? "quest-option--correct" : ""} ${submitted && selected.includes(option) && !question.answers.includes(option) ? "quest-option--wrong" : ""}`} onClick={() => onToggle(option)}><span>{String.fromCharCode(65 + index)}</span><strong>{option}</strong>{selected.includes(option) && !submitted && <Check size={16} />}{submitted && question.answers.includes(option) && <Check size={16} />}{submitted && selected.includes(option) && !question.answers.includes(option) && <X size={16} />}</button>)}</div><div className="sheet-actions">{!submitted ? <button type="button" className="answer-action boss-answer-action" onClick={onSubmit} disabled={!selected.length}>보스에게 답하기 <ArrowRight size={16} /></button> : correct ? <button type="button" className="answer-action answer-action--success" onClick={onClear}>칭호 받기 <Crown size={16} /></button> : <button type="button" className="retry-action" onClick={onRetry}><RotateCcw size={15} /> 다시 도전</button>}</div>{submitted && <div className={correct ? "quest-feedback quest-feedback--success" : "quest-feedback quest-feedback--wrong"}><span>{correct ? <Check size={18} /> : <X size={18} />}</span><div><strong>{correct ? "보스의 봉인이 흔들립니다!" : "보스가 아직 길을 막고 있어요."}</strong><p>{question.explanation}</p></div></div>}</div></section></main>;
}

/** Design: a compact reward reveal makes the title feel earned before the usual unlock scene begins. */
function BossClearScreen({ quest, boss, onContinue, onMap }: { quest: Quest; boss: BossChallenge; onContinue: () => void; onMap: () => void }) {
  return <main className="quest-app"><Header onMap={onMap} title="칭호 획득" focus={`관문 ${String(quest.id).padStart(2, "0")} · 보스 격파`} /><section className="boss-clear-page"><div className={`boss-clear-card boss-clear-card--${quest.tone}`}><div className="boss-clear-card__burst">✦</div><div className="boss-clear-card__seal"><Crown size={42} /></div><p className="quest-kicker">보스 격파 · 특별 칭호 획득</p><h1>{boss.rewardTitle}</h1><p><b>{quest.title}</b>의 마지막 봉인을 풀었습니다. 이 칭호는 업적 보관소에 기록됩니다.</p><div className="boss-clear-card__title"><span>획득 칭호</span><strong>{boss.rewardTitle}</strong></div><button type="button" className="next-quest boss-clear-card__button" onClick={onContinue}>관문 통과 기록하기 <ArrowRight size={17} /></button></div></section></main>;
}

/** Design: the review sprint keeps a single weak concept visible, so five questions feel like a focused comeback rather than another full quest. */
function MiniReviewScreen({ queue, weakQuestId, index, selected, submitted, correct, attempts, onBack, onToggle, onSubmit, onRetry, onNext }: { queue: MiniReviewItem[]; weakQuestId: number; index: number; selected: string[]; submitted: boolean; correct: boolean; attempts: number; onBack: () => void; onToggle: (option: string) => void; onSubmit: () => void; onRetry: () => void; onNext: () => void }) {
  const item = queue[index];
  const quest = quests[weakQuestId - 1];
  return <main className="quest-app"><Header onMap={onBack} title="약점 복습전" focus={`집중 개념 · ${quest.concept}`} /><section className={`mini-review-page mini-review-page--${quest.tone}`}><div className="mini-review-header"><div><p className="quest-kicker">오답 분석 기반 · 5문항 집중전</p><h1><em>{quest.concept}</em><br />다시 단단하게.</h1><p>가장 많이 막힌 개념을 골라 오답 확인과 약점 강화 문제를 섞었습니다.</p></div><div className="mini-review-score"><span>집중 관문</span><strong>{String(weakQuestId).padStart(2, "0")}</strong><b>시도 {attempts}회</b></div></div><div className="mini-review-steps" aria-label="미니 복습전 진행률">{queue.map((question, step) => <span key={`${question.prompt}-${step}`} className={step < index ? "mini-review-step mini-review-step--done" : step === index ? "mini-review-step mini-review-step--current" : "mini-review-step"}>{step < index ? <Check size={14} /> : step + 1}</span>)}</div><div className="mini-review-sheet"><div className="mini-review-sheet__top"><span className={`quest-tag quest-tag--${quest.tone}`}>{item.source}</span><span>문제 {index + 1} / 5</span></div><h2>{item.prompt}</h2>{item.multiple && <p className="multi-note">정답을 모두 선택하세요.</p>}{item.input ? <label className="direct-answer"><span>숫자로 답을 입력하세요</span><input type="text" inputMode="decimal" value={selected[0] ?? ""} disabled={submitted} onChange={(event) => onToggle(event.target.value)} placeholder="정답 입력" aria-label="정답 입력" /></label> : <div className="quest-options">{item.options.map((option, optionIndex) => <button type="button" key={option} disabled={submitted} className={`quest-option ${selected.includes(option) ? "quest-option--selected" : ""} ${submitted && item.answers.includes(option) ? "quest-option--correct" : ""} ${submitted && selected.includes(option) && !item.answers.includes(option) ? "quest-option--wrong" : ""}`} onClick={() => onToggle(option)}><span>{String.fromCharCode(65 + optionIndex)}</span><strong>{option}</strong>{selected.includes(option) && !submitted && <Check size={16} />}{submitted && item.answers.includes(option) && <Check size={16} />}{submitted && selected.includes(option) && !item.answers.includes(option) && <X size={16} />}</button>)}</div>}<div className="sheet-actions">{!submitted ? <button type="button" className="answer-action mini-review-answer" onClick={onSubmit} disabled={!selected.length}>집중 답안 제출 <ArrowRight size={16} /></button> : correct ? <button type="button" className="answer-action answer-action--success" onClick={onNext}>{index === queue.length - 1 ? "결과 확인" : "다음 집중 문제"} <ArrowRight size={16} /></button> : <button type="button" className="retry-action" onClick={onRetry}><RotateCcw size={15} /> 규칙 다시 보고 풀기</button>}</div>{submitted && <div className={correct ? "quest-feedback quest-feedback--success" : "quest-feedback quest-feedback--wrong"}><span>{correct ? <Check size={18} /> : <X size={18} />}</span><div><strong>{correct ? "약점 규칙을 잡았어요." : "한 번 더 규칙을 확인해요."}</strong><p>{item.explanation}</p></div></div>}</div></section></main>;
}

/** Design: the result is an encouraging recovery stamp, not a performance leaderboard. */
function MiniReviewResultScreen({ quest, correctCount, attempts, onNotes, onRestart }: { quest: Quest; correctCount: number; attempts: number; onNotes: () => void; onRestart: () => void }) {
  const recovered = correctCount >= 4;
  const title = correctCount === 5 ? "약점 정복!" : recovered ? "규칙 회복!" : "한 번 더 단단하게!";
  const copy = correctCount === 5 ? "다섯 문제를 모두 통과했습니다. 이제 이 개념은 자신 있게 다시 써 볼 수 있어요." : recovered ? "핵심 규칙을 다시 잡았습니다. 오답 노트의 남은 문제도 도전해 보세요." : "답을 고를 때 경계값과 상황의 목적을 한 번 더 확인하면 더 단단해져요.";
  return <main className="quest-app"><Header onMap={onNotes} title="복습전 결과" focus={`집중 개념 · ${quest.concept}`} /><section className="mini-result-page"><div className={`mini-result-card mini-result-card--${quest.tone}`}><div className="mini-result-card__seal"><ShieldCheck size={38} /></div><p className="quest-kicker">5문항 미니 복습전 완료</p><h1>{title}</h1><p>{copy}</p><div className="mini-result-card__stats"><span><Target size={18} /> 정답 <b>{correctCount} / 5</b></span><span><RotateCcw size={18} /> 시도 <b>{attempts}회</b></span></div><div className="mini-result-card__message">약점 개념 <b>{quest.concept}</b></div><div className="mini-result-card__actions"><button type="button" className="map-button" onClick={onNotes}>오답 노트로</button><button type="button" className="next-quest" onClick={onRestart}>5문항 다시 도전 <RotateCcw size={16} /></button></div></div></section></main>;
}

function MistakeBookScreen({ notes, filter, onFilter, onMap, onPractice, onAllPractice, onMiniReview, onReviewConcept }: { notes: WrongNote[]; filter: NoteFilter; onFilter: (value: NoteFilter) => void; onMap: () => void; onPractice: (note: WrongNote) => void; onAllPractice: () => void; onMiniReview: () => void; onReviewConcept: (questId: number) => void }) {
  const filteredNotes = filter === "all" ? notes : notes.filter((note) => note.questId === filter);
  const conceptStats = Object.values(notes.reduce<Record<string, { count: number; questId: number }>>((stats, note) => { const concept = quests[note.questId - 1].concept; stats[concept] = { count: (stats[concept]?.count ?? 0) + note.wrongCount, questId: note.questId }; return stats; }, {})).sort((a, b) => b.count - a.count);
  const primaryWeak = conceptStats[0];
  return <main className="quest-app"><Header onMap={onMap} /><section className="notes-page"><div className="notes-heading"><div><p className="quest-kicker">오답 노트 · 다시 풀기</p><h1>틀린 문제만<br /><em>다시 잡아요.</em></h1><p>빨간 도장을 받은 문제는 여기에 모입니다.<br />정답을 맞히면 노트에서 사라져요.</p></div><div className="notes-count"><AlertTriangle size={23} /><strong>{notes.length}</strong><span>남은 문제</span></div></div>{notes.length > 0 && <><div className="notes-tools"><div className="note-filters"><button type="button" className={filter === "all" ? "note-filter note-filter--active" : "note-filter"} onClick={() => onFilter("all")}>전체 <b>{notes.length}</b></button>{quests.map((quest) => <button type="button" key={quest.id} className={filter === quest.id ? `note-filter note-filter--${quest.tone} note-filter--active` : `note-filter note-filter--${quest.tone}`} onClick={() => onFilter(quest.id)}>관문 {quest.id} <b>{notes.filter((note) => note.questId === quest.id).length}</b></button>)}</div><button type="button" className="all-review-button" onClick={onAllPractice} disabled={!filteredNotes.length}><RotateCcw size={15} /> {filter === "all" ? "전체 다시 풀기" : "이 관문 다시 풀기"}</button></div><div className="weak-summary"><div className="weak-summary__heading"><div><p className="quest-kicker">오답 분석</p><h2>내가 자주 막히는 곳</h2></div><span>카드를 눌러 이론 복습</span></div><div className="weak-summary__grid">{conceptStats.slice(0, 3).map((item, index) => <button type="button" className={`weak-item weak-item--${index === 0 ? "hot" : "normal"}`} key={item.questId} onClick={() => onReviewConcept(item.questId)}><strong>{index + 1}</strong><span>{quests[item.questId - 1].concept}<small>이론 다시 보기 →</small></span><b>{item.count}회</b></button>)}</div></div>{primaryWeak && <section className="mini-review-invite"><div><p className="quest-kicker">약점 집중 · 5문항</p><h2><em>{quests[primaryWeak.questId - 1].concept}</em> 미니 복습전</h2><p>오답 횟수가 가장 많은 개념의 실제 문제은행으로 5문항을 구성합니다. 오답 기록은 그대로 두고, 약한 규칙만 집중 연습해요.</p><span><Target size={15} /> 현재 약점 {primaryWeak.count}회 · 관문 {String(primaryWeak.questId).padStart(2, "0")}</span></div><button type="button" onClick={onMiniReview}>5문항 도전 <ArrowRight size={17} /></button></section>}</>}{notes.length === 0 ? <div className="note-empty"><div><BookOpenCheck size={38} /></div><h2>오답 노트가 비었어요.</h2><p>문제를 풀다가 틀린 문제는<br />여기에 자동으로 기록됩니다.</p><button type="button" onClick={onMap}>퀘스트로 돌아가기 <ArrowRight size={16} /></button></div> : filteredNotes.length === 0 ? <div className="note-empty note-empty--small"><div><Check size={30} /></div><h2>이 관문의 오답은 없어요.</h2><p>다른 관문을 골라 보거나<br />새 문제에 도전해 보세요.</p></div> : <div className="note-list">{filteredNotes.map((note, index) => { const quest = quests[note.questId - 1]; return <article className={`note-card note-card--${quest.tone}`} key={note.id}><div className="note-card__stamp">다시!</div><div className="note-card__top"><span>NO. {String(index + 1).padStart(2, "0")} · {quest.place}</span><b>{note.wrongCount}번 틀림</b></div><h2>{note.prompt}</h2><div className="note-card__answer"><span>내가 고른 답</span><strong>{note.selected.join(" · ") || "기록 없음"}</strong><span>정답</span><strong>{note.answers.join(" · ")}</strong></div><p>{note.explanation}</p><button type="button" onClick={() => onPractice(note)}>이 문제 다시 풀기 <ArrowRight size={16} /></button></article>; })}</div>}</section></main>;
}

function MistakePracticeScreen({ note, selected, submitted, correct, showSolvedStamp, onBack, onToggle, onSubmit, onRetry }: { note: WrongNote; selected: string[]; submitted: boolean; correct: boolean; showSolvedStamp: boolean; onBack: () => void; onToggle: (option: string) => void; onSubmit: () => void; onRetry: () => void }) {
  const quest = quests[note.questId - 1];
  return <main className="quest-app"><Header onMap={onBack} title="오답 노트" /><section className="note-play-page"><button type="button" className="back-link" onClick={onBack}><ArrowLeft size={15} /> 오답 노트로 돌아가기</button><div className="note-play-heading"><div><p className="quest-kicker">다시 도전 · {quest.place}</p><h1>이번에는<br /><em>통과할 차례!</em></h1></div><div className="note-play-badge">틀린 횟수 <strong>{note.wrongCount}</strong></div></div><div className="question-sheet note-play-sheet"><div className="sheet-header"><span className={`quest-tag quest-tag--${quest.tone}`}>{quest.concept}</span><span className="sheet-status">오답 복습</span></div><h3>{note.prompt}</h3>{note.multiple && <p className="multi-note">정답을 모두 선택하세요.</p>}{note.input ? <label className="direct-answer"><span>숫자로 답을 입력하세요</span><input type="text" inputMode="decimal" value={selected[0] ?? ""} disabled={submitted} onChange={(event) => onToggle(event.target.value)} placeholder="정답 입력" aria-label="정답 입력" /></label> : <div className="quest-options">{note.options.map((option, index) => <button type="button" key={option} disabled={submitted} className={`quest-option ${selected.includes(option) ? "quest-option--selected" : ""} ${submitted && note.answers.includes(option) ? "quest-option--correct" : ""} ${submitted && selected.includes(option) && !note.answers.includes(option) ? "quest-option--wrong" : ""}`} onClick={() => onToggle(option)}><span>{String.fromCharCode(65 + index)}</span><strong>{option}</strong>{submitted && note.answers.includes(option) && <Check size={16} />}{submitted && selected.includes(option) && !note.answers.includes(option) && <X size={16} />}</button>)}</div>}<div className="sheet-actions">{!submitted ? <button type="button" className="answer-action" onClick={onSubmit} disabled={!selected.length}>정답 제출 <ArrowRight size={16} /></button> : correct ? <button type="button" className="answer-action answer-action--success" onClick={onBack}>오답 노트로 돌아가기 <ArrowRight size={16} /></button> : <button type="button" className="retry-action" onClick={onRetry}><RotateCcw size={15} /> 다시 고르기</button>}</div>{submitted && <div className={correct ? "quest-feedback quest-feedback--success" : "quest-feedback quest-feedback--wrong"}><span>{correct ? <Check size={18} /> : <X size={18} />}</span><div><strong>{correct ? "오답 노트에서 지웠어요." : "빨간 도장이 한 번 더 찍혔어요."}</strong><p>{note.explanation}</p></div></div>}</div>{showSolvedStamp && <div className="solved-overlay" role="status"><div className="solved-stamp">해결<br />완료</div><p>이 문제는 오답 노트에서 사라져요!</p></div>}</section></main>;
}

function UnlockScreen({ sequence, noteCount, onMap, onNext, onAchievements }: { sequence: UnlockSequence; noteCount: number; onMap: () => void; onNext: () => void; onAchievements: () => void }) {
  const [phase, setPhase] = useState(0);
  const fromQuest = quests[sequence.from - 1];
  const nextQuest = sequence.next ? quests[sequence.next - 1] : null;
  const fromIndex = sequence.from - 1;
  const nextIndex = sequence.next ? sequence.next - 1 : fromIndex;
  const point = (index: number) => ({ x: 14 + (index % 4) * 24, y: 20 + Math.floor(index / 4) * 30 });
  const from = point(fromIndex);
  const to = point(nextIndex);
  useEffect(() => { const timers = [window.setTimeout(() => setPhase(1), 360), window.setTimeout(() => setPhase(2), 1320), window.setTimeout(() => setPhase(3), 2280)]; return () => timers.forEach(window.clearTimeout); }, []);
  const message = phase === 0 ? "통과 기록을 지도에 새기는 중" : phase === 1 ? "빛의 길이 다음 관문까지 이어집니다" : phase === 2 ? "봉인에 금이 갔습니다" : nextQuest ? "다음 관문이 열렸습니다" : "경계의 성 모든 관문을 통과했습니다";
  return <main className="quest-app"><Header onMap={phase >= 3 ? onMap : undefined} onAchievements={phase >= 3 ? onAchievements : undefined} noteCount={noteCount} title="관문 해금" focus={`관문 ${String(sequence.from).padStart(2, "0")} 통과`} /><section className="unlock-page"><div className="unlock-heading"><p className="quest-kicker">관문 통과 · 기록 갱신</p><h1>{fromQuest.title}<br /><em>길이 열립니다.</em></h1><p>{message}</p></div><div className={`unlock-map unlock-map--phase-${phase}`}><svg className="unlock-route-svg" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><line className="unlock-route-base" x1={from.x} y1={from.y} x2={to.x} y2={to.y} /><line className="unlock-route-light" x1={from.x} y1={from.y} x2={to.x} y2={to.y} /></svg><div className="unlock-gate unlock-gate--cleared" style={{ left: `${from.x}%`, top: `${from.y}%` }}><QuestEmblem tone={fromQuest.tone} done /><span className="unlock-gate__label">관문 {String(sequence.from).padStart(2, "0")}<b>통과</b></span></div>{nextQuest ? <div className="unlock-gate unlock-gate--next" style={{ left: `${to.x}%`, top: `${to.y}%` }}><QuestEmblem tone={nextQuest.tone} locked={phase < 3} /><span className="unlock-gate__label">관문 {String(nextQuest.id).padStart(2, "0")}<b>{phase < 3 ? "봉인" : "열림"}</b></span>{phase >= 2 && <i className="unlock-crack">봉인 해제</i>}</div> : <div className="unlock-gate unlock-gate--final" style={{ left: `${to.x}%`, top: `${to.y}%` }}><Trophy size={46} /><span className="unlock-gate__label">최종 관문<b>완료</b></span></div>}<div className="unlock-spark unlock-spark--a">✦</div><div className="unlock-spark unlock-spark--b">✦</div><div className="unlock-spark unlock-spark--c">✦</div></div><div className="unlock-record"><div><Clock3 size={18} /><span>이번 기록</span><strong>{formatTime(sequence.result.last ?? 0)}</strong></div><div><Target size={18} /><span>정확도</span><strong>{sequence.result.accuracy}%</strong></div><div><Crown size={18} /><span>최고 기록</span><strong>{formatTime(sequence.result.best ?? 0)}</strong></div></div><div className="unlock-actions"><button type="button" className="map-button" onClick={onMap} disabled={phase < 3}>지도에서 확인</button><button type="button" className="next-quest unlock-next-button" onClick={onNext} disabled={phase < 3}>다음 관문 입장 <ArrowRight size={17} /></button></div></section></main>;
}

function ResultScreen({ quest, result, noteCount, onMap, onNotes, onNext }: { quest: Quest; result: RecordValue; noteCount: number; onMap: () => void; onNotes: () => void; onNext: () => void }) {
  const nextQuest = quest.id < quests.length ? quests[quest.id] : null;
  return <main className="quest-app"><Header onMap={onMap} onNotes={onNotes} noteCount={noteCount} focus={nextQuest ? `${String(nextQuest.id).padStart(2, "0")} · 봉인 해제` : "최종 관문 통과"} /><section className="result-page"><div className={`result-emblem result-emblem--${quest.tone}`}><Trophy size={34} /></div><p className="quest-kicker">차시 통과 · {quest.gate}</p><h1>{quest.title}<br /><em>관문 통과!</em></h1><p className="result-copy">{quest.questions.length}문항을 끝까지 풀어 {quest.place}을 통과했어요. 다음 지도 조각이 모습을 드러냈습니다.</p><div className="result-stats"><div><Clock3 size={19} /><span>이번 기록</span><strong>{formatTime(result.last ?? 0)}</strong></div><div><Target size={19} /><span>정확도</span><strong>{result.accuracy}%</strong></div><div><Sparkles size={19} /><span>최고 기록</span><strong>{formatTime(result.best ?? 0)}</strong></div></div>{nextQuest && <div className="unlock-reward"><ShieldCheck size={19} /><div><span>봉인 해제</span><strong>관문 {String(nextQuest.id).padStart(2, "0")} · {nextQuest.title}</strong></div><b>열림</b></div>}<div className="result-note"><Crown size={17} /><span>{result.last === result.best ? "개인 최고 기록을 새로 남겼어요." : "나의 최고 기록과 비교해 보세요."}</span></div><div className="result-actions"><button type="button" className="map-button" onClick={onMap}>지도 확인</button>{noteCount > 0 && <button type="button" className="map-button" onClick={onNotes}>오답 노트 {noteCount}개</button>}{quest.id < quests.length && <button type="button" className="next-quest" onClick={onNext}>다음 관문 열기 <ArrowRight size={17} /></button>}</div></section></main>;
}
